B.bzn=new A.ai(B.bC,["integer","Rows per page. Bases: 1\u201320, entries: 1\u201320, chunks: 1\u20135. Defaults: bases 20, entries 10, chunks 5."],t.w)
B.byM=new A.ai(B.bCE,[B.bzo,B.bzp,B.bzg,B.bzy,B.bzn],t.vb)
